def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Maximal runs of a non-background color along each edge.
    def runs(side):
        n = h if side in ("L", "R") else w

        def cell(i):
            if side == "L":
                return grid[i][0]
            if side == "R":
                return grid[i][w - 1]
            if side == "T":
                return grid[0][i]
            return grid[h - 1][i]

        result = []
        i = 0
        while i < n:
            color = cell(i)
            if color == bg:
                i += 1
                continue
            j = i + 1
            while j < n and cell(j) == color:
                j += 1
            result.append((color, list(range(i, j))))
            i = j
        return result

    def coord(side, i, step):
        if side == "L":
            return i, step
        if side == "R":
            return i, w - 1 - step
        if side == "T":
            return step, i
        return h - 1 - step, i

    def paint_ray(side, i, color, endpoint=None):
        limit = w if side in ("L", "R") else h
        for step in range(1, limit):
            r, c = coord(side, i, step)
            if endpoint == (r, c):
                out[r][c] = 4
                break
            if grid[r][c] == bg:
                out[r][c] = color
            else:
                break

    def first_marker(side, i, stripe_color):
        limit = w if side in ("L", "R") else h
        for step in range(1, limit):
            r, c = coord(side, i, step)
            v = grid[r][c]
            if v != bg:
                if v != stripe_color:
                    return (r, c, v)
                return None
        return None

    for a, b in (("L", "R"), ("T", "B")):
        aruns, bruns = runs(a), runs(b)
        for color, ai in aruns:
            for color2, bi in bruns:
                if color != color2 or len(ai) != len(bi):
                    continue
                n = len(ai)
                active = []
                for k in range(n):
                    ma = first_marker(a, ai[k], color)
                    mb = first_marker(b, bi[k], color)
                    if ma:
                        active.append((a, ai[k], b, bi[k], ma))
                    if mb:
                        active.append((b, bi[k], a, ai[k], mb))

                for source, si, other, oi, marker in active:
                    r, c, marker_color = marker
                    paint_ray(source, si, marker_color, (r, c))
                    # The matching stripe projects a full ray on the same offset.
                    limit = w if other in ("L", "R") else h
                    for step in range(1, limit):
                        y, x = coord(other, oi, step)
                        if grid[y][x] == bg:
                            out[y][x] = marker_color

    return out
